def sort_third(l: list):
    # Separate the elements at indices divisible by 3 and sort them
    third_group = []
    other_group = []
    for i, val in enumerate(l):
        if i % 3 == 0:
            third_group.append(val)
        else:
            other_group.append(val)

    # Interleave the sorted third group with the other group
    result = []
    i = 0
    while i < len(third_group):
        result.append(third_group[i])
        i += 1
    while i < len(l):
        result.append(l[i])
        i += 1

    return result

