    count_up_to(18) => [2,3,5,7,11,13,17]
    """
    if n <= 2:
        return []

    primes = []
    for i in range(2, n):
        is_prime = True
        for j in range(2, int(i ** 0.5) + 1):
            if i % j == 0:
                is_prime = False
                break
        if is_prime:
            primes.append(i)
    return primes

